import type { AIGeneratedFile, AIModel, ChatMessage } from '../types/ide';
import { isSensitiveFilePath } from './aiContextBuilder';

export { selectRelevantContext, isSensitiveFilePath, redactInlineSecrets } from './aiContextBuilder';
export type { ContextBundle } from './aiContextBuilder';

export interface AIRequestResult {
  success: boolean;
  content?: string;
  error?: string;
  aborted?: boolean;
  usage?: {
    promptTokens: number;
    completionTokens: number;
    totalTokens: number;
  };
}

/**
 * Validate that an AI-generated file path is strictly relative, inside the workspace,
 * and not targeting sensitive files (.env, .git, keys).
 */
export function isSafeGeneratedPath(rawPath: string): boolean {
  if (!rawPath || typeof rawPath !== 'string') return false;
  if (rawPath.includes('\0')) return false;
  const trimmed = rawPath.trim();
  if (!trimmed || trimmed.startsWith('/') || trimmed.startsWith('\\')) return false;
  if (/^[a-zA-Z]:/.test(trimmed)) return false; // Windows drive letter
  const normalized = trimmed.replace(/\\/g, '/');
  const segments = normalized.split('/');
  if (segments.some((seg) => seg === '..' || seg === '.')) return false;
  if (isSensitiveFilePath(normalized)) return false;
  return true;
}

/**
 * Parse file code blocks generated by the LLM so projects & multi-file edits
 * can be previewed and applied safely into the IDE workspace.
 */
export function parseGeneratedFilesFromResponse(markdown: string): AIGeneratedFile[] {
  const results: AIGeneratedFile[] = [];
  const seenPaths = new Set<string>();

  const fenceRegex = /```([^\n]*)\n([\s\S]*?)```/g;
  let match: RegExpExecArray | null;

  while ((match = fenceRegex.exec(markdown)) !== null) {
    const header = (match[1] || '').trim();
    const code = match[2] ?? '';

    let filePath = '';
    let language = 'typescript';

    const attrMatch = header.match(/file=["']?([^"'\s]+)["']?/i);
    if (attrMatch) {
      filePath = attrMatch[1].trim();
      const langCandidate = header.split(/\s+/)[0];
      if (langCandidate && !langCandidate.includes('=')) {
        language = langCandidate;
      }
    } else if (/^file:/i.test(header)) {
      filePath = header.replace(/^file:/i, '').trim().split(/\s+/)[0];
    } else if (/[./\\]/.test(header) && !header.includes(' ')) {
      filePath = header.trim();
    }

    if (!filePath || !isSafeGeneratedPath(filePath)) continue;
    filePath = filePath.replace(/\\/g, '/');

    const ext = filePath.split('.').pop()?.toLowerCase() || '';
    if (ext === 'c' || ext === 'h') language = 'c';
    else if (ext === 'py') language = 'python';
    else if (ext === 'json') language = 'json';
    else if (ext === 'html') language = 'html';
    else if (ext === 'css') language = 'css';
    else if (ext === 'md') language = 'markdown';
    else if (ext === 'js' || ext === 'jsx') language = 'javascript';
    else if (ext === 'ts' || ext === 'tsx') language = 'typescript';

    if (seenPaths.has(filePath)) {
      const idx = results.findIndex((r) => r.path === filePath);
      if (idx >= 0) results[idx] = { path: filePath, content: code, language };
    } else {
      seenPaths.add(filePath);
      results.push({ path: filePath, content: code, language });
    }
  }

  return results;
}

export async function getBackendAiKeyStatuses(): Promise<{
  configuredProviders: Record<string, boolean>;
  statuses: Record<string, string>;
}> {
  try {
    const res = await fetch('/api/ai/keys/status', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({}),
    });
    const data = await res.json().catch(() => ({}));
    return {
      configuredProviders: data.configuredProviders || {},
      statuses: data.statuses || {},
    };
  } catch {
    return { configuredProviders: {}, statuses: {} };
  }
}

export async function saveBackendAiKey(providerKey: string, apiKey: string): Promise<{
  success: boolean;
  configuredProviders: Record<string, boolean>;
  statuses: Record<string, string>;
}> {
  try {
    const res = await fetch('/api/ai/keys/set', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ providerKey, apiKey }),
    });
    const data = await res.json().catch(() => ({}));
    return {
      success: Boolean(data.success),
      configuredProviders: data.configuredProviders || {},
      statuses: data.statuses || {},
    };
  } catch {
    return { success: false, configuredProviders: {}, statuses: {} };
  }
}

export async function testProviderConnection(params: {
  providerKey: string;
  format: 'gemini' | 'openai' | 'anthropic';
  baseUrl?: string;
  modelId?: string;
  apiKey?: string;
}): Promise<{ success: boolean; modelsCount?: number; error?: string }> {
  try {
    const res = await fetch('/api/ai/test', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(params),
    });
    return await res.json().catch(() => ({ success: false, error: `HTTP ${res.status}` }));
  } catch (err: any) {
    return { success: false, error: err?.message || 'Could not reach AI gateway.' };
  }
}

export async function sendModelRequest(params: {
  model: AIModel;
  apiKey?: string;
  messages: Pick<ChatMessage, 'sender' | 'content'>[];
  systemPrompt: string;
  temperature?: number;
  signal?: AbortSignal;
  onDelta?: (partialText: string) => void;
}): Promise<AIRequestResult> {
  const { model, apiKey = '', messages, systemPrompt, temperature = 0.2, signal, onDelta } = params;

  const formattedMessages = messages
    .filter((m) => m.sender === 'user' || m.sender === 'assistant')
    .slice(-16)
    .map((m) => ({
      role: m.sender === 'assistant' ? 'assistant' : 'user',
      content: m.content,
    }));

  const payload = {
    format: model.apiFormat,
    baseUrl: model.baseUrl,
    providerKey: model.providerKey,
    ...(apiKey ? { apiKey } : {}),
    modelId: model.modelId,
    messages: formattedMessages,
    systemPrompt,
    temperature,
  };

  if (onDelta) {
    try {
      const res = await fetch('/api/ai/chat-stream', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
        signal,
      });

      if (res.ok && res.body) {
        const reader = res.body.getReader();
        const decoder = new TextDecoder();
        let buffer = '';
        let fullText = '';
        let finalUsage: AIRequestResult['usage'];

        while (true) {
          const { value, done } = await reader.read();
          if (done) break;
          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';
          for (const line of lines) {
            if (!line.startsWith('data: ')) continue;
            const jsonStr = line.slice(6).trim();
            if (!jsonStr) continue;
            const evt = JSON.parse(jsonStr);
            if (evt.error) {
              return { success: false, error: evt.error, aborted: evt.aborted };
            }
            if (evt.delta) {
              fullText += evt.delta;
              onDelta(fullText);
            }
            if (evt.done) {
              finalUsage = evt.usage;
            }
          }
        }
        return { success: true, content: fullText, usage: finalUsage };
      }
    } catch (err: any) {
      if (err?.name === 'AbortError') {
        return { success: false, aborted: true, error: 'Generation stopped.' };
      }
    }
  }

  try {
    const res = await fetch('/api/ai/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal,
    });
    const data = await res.json().catch(() => null);
    if (data && (data.success || data.error)) {
      return data;
    }
  } catch (err: any) {
    if (err?.name === 'AbortError') {
      return { success: false, aborted: true, error: 'Generation stopped.' };
    }
  }

  return {
    success: false,
    error: 'Could not reach AI gateway proxy (/api/ai/chat). Make sure Vite dev server is running.',
  };
}

export async function fetchAvailableProviderModels(params: {
  format: 'gemini' | 'openai' | 'anthropic';
  baseUrl?: string;
  providerKey?: string;
  apiKey?: string;
}): Promise<{
  success: boolean;
  models?: { modelId: string; name: string; description: string; contextWindow: string }[];
  error?: string;
}> {
  try {
    const res = await fetch('/api/ai/models', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(params),
    });
    const data = await res.json().catch(() => ({}));
    if (data && (data.success || data.error)) return data;
  } catch (err: any) {
    return { success: false, error: err?.message || 'Failed to reach model discovery endpoint.' };
  }

  return { success: false, error: 'Could not reach model discovery endpoint.' };
}
